function minimumOperations(num: string): number {
    const n = num.length;
    const f: number[][] = Array.from({ length: n }, () => Array.from({ length: 25 }, () => -1));
    const dfs = (i: number, k: number): number => {
        if (i === n) {
            return k === 0 ? 0 : n;
        }
        if (f[i][k] !== -1) {
            return f[i][k];
        }
        f[i][k] = dfs(i + 1, k) + 1;
        f[i][k] = Math.min(f[i][k], dfs(i + 1, (k * 10 + Number(num[i])) % 25));
        return f[i][k];
    };
    return dfs(0, 0);
}

impl Solution {
    pub fn minimum_operations(num: String) -> i32 {
        let n = num.len();
        let bytes = num.as_bytes();

        let mut memo = vec![vec![-1; 25]; n];

        fn dfs(i: usize, k: usize, n: usize, bytes: &[u8], memo: &mut Vec<Vec<i32>>) -> i32 {
            if i == n {
                return if k == 0 { 0 } else { n as i32 };
            }

            if memo[i][k] != -1 {
                return memo[i][k];
            }

            // delete current digit
            let mut res = dfs(i + 1, k, n, bytes, memo) + 1;

            // keep current digit
            let digit = (bytes[i] - b'0') as usize;
            let nk = (k * 10 + digit) % 25;
            res = res.min(dfs(i + 1, nk, n, bytes, memo));

            memo[i][k] = res;
            res
        }

        dfs(0, 0, n, &bytes, &mut memo)
    }
}

public class Solution {
    private int[,] memo;
    private string num;
    private int n;

    public int MinimumOperations(string num) {
        this.num = num;
        n = num.Length;
        memo = new int[n, 25];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 25; j++) {
                memo[i, j] = -1;
            }
        }

        return Dfs(0, 0);
    }

    private int Dfs(int i, int k) {
        if (i == n) {
            return k == 0 ? 0 : n;
        }

        if (memo[i, k] != -1) {
            return memo[i, k];
        }

        // delete current digit
        int res = Dfs(i + 1, k) + 1;

        // keep current digit
        int digit = num[i] - '0';
        int nk = (k * 10 + digit) % 25;
        res = Math.Min(res, Dfs(i + 1, nk));

        memo[i, k] = res;
        return res;
    }
}
